import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'app_state.dart';
import 'domain/models.dart';
import 'screens/scanner_screen.dart';
import 'screens/prepare_route_screen.dart';
import 'screens/address_editor_dialog.dart';
import 'services/location_service.dart';

void main()=>runApp(const DeliveryApp());
class DeliveryApp extends StatefulWidget{const DeliveryApp({super.key});@override State<DeliveryApp> createState()=>_DeliveryAppState();}
class _DeliveryAppState extends State<DeliveryApp>{final state=AppState();@override void initState(){super.initState();state.init();}@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Rotas Entregas',theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:HomePage(state:state));}
class HomePage extends StatefulWidget{final AppState state;const HomePage({super.key,required this.state});@override State<HomePage> createState()=>_HomePageState();}
enum _ActiveFilter{all,pending,absent,problem,skipped}
class _HomePageState extends State<HomePage>{
 _ActiveFilter filter=_ActiveFilter.all;bool retrying=false;
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:widget.state,builder:(context,_){final s=widget.state;if(s.loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));final active=s.packages.where((p)=>p.status!=DeliveryStatus.delivered).toList();final delivered=s.packages.where((p)=>p.status==DeliveryStatus.delivered).toList()..sort((a,b)=>(b.completedAt??b.scannedAt).compareTo(a.completedAt??a.scannedAt));return DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Minha rota'),bottom:TabBar(tabs:[Tab(text:'Endereços (${active.length})'),Tab(text:'Entregues (${delivered.length})')]),actions:[PopupMenuButton<String>(tooltip:'Adicionar',icon:const Icon(Icons.add_box_outlined),onSelected:(v){if(v=='manual')_manual(context);if(v=='paste')_pasteList(context);},itemBuilder:(_)=>const [PopupMenuItem(value:'manual',child:ListTile(leading:Icon(Icons.edit_location_alt_outlined),title:Text('Adicionar endereço'))),PopupMenuItem(value:'paste',child:ListTile(leading:Icon(Icons.content_paste),title:Text('Colar lista')))]),PopupMenuButton<String>(tooltip:'Mais opções',onSelected:(v){if(v=='clear')_confirmClear(context);},itemBuilder:(_)=>const [PopupMenuItem(value:'clear',child:ListTile(leading:Icon(Icons.delete_outline),title:Text('Limpar todos os pacotes')))])]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ScannerScreen(state:s))),icon:const Icon(Icons.camera_alt),label:const Text('Escanear')),body:TabBarView(children:[_activeView(context,s,active),_deliveredView(delivered)])));});
 Widget _activeView(BuildContext context,AppState s,List<DeliveryPackage> active){final absent=active.where((p)=>p.status==DeliveryStatus.absent).length;final problems=active.where((p)=>p.status==DeliveryStatus.addressProblem).length;final skipped=active.where((p)=>p.status==DeliveryStatus.skipped).length;final pending=active.where((p)=>p.status==DeliveryStatus.pending||p.status==DeliveryStatus.current).length;final retry=absent+problems+skipped;final visible=active.where((p){switch(filter){case _ActiveFilter.all:return true;case _ActiveFilter.pending:return p.status==DeliveryStatus.pending||p.status==DeliveryStatus.current;case _ActiveFilter.absent:return p.status==DeliveryStatus.absent;case _ActiveFilter.problem:return p.status==DeliveryStatus.addressProblem;case _ActiveFilter.skipped:return p.status==DeliveryStatus.skipped;}}).toList();return Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,12,16,4),child:Row(children:[Expanded(child:_stat('${active.length}','Ativos')),Expanded(child:_stat('${s.reviewCount}','Revisar')),Expanded(child:_stat('$absent','Ausentes')),Expanded(child:_stat('$problems','Problemas'))])),SizedBox(height:44,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:[_chip('Todos',active.length,_ActiveFilter.all),_chip('Pendentes',pending,_ActiveFilter.pending),_chip('Ausentes',absent,_ActiveFilter.absent),_chip('Problemas',problems,_ActiveFilter.problem),_chip('Pulados',skipped,_ActiveFilter.skipped)])),if(retry>0)Padding(padding:const EdgeInsets.fromLTRB(16,8,16,0),child:SizedBox(width:double.infinity,child:FilledButton.tonalIcon(onPressed:retrying?null:()=>_retryPending(context),icon:retrying?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.replay),label:Padding(padding:const EdgeInsets.all(11),child:Text(retrying?'PREPARANDO...':'2ª TENTATIVA • $retry PARADA${retry==1?'':'S'}'))))),if(active.isNotEmpty)Padding(padding:const EdgeInsets.symmetric(horizontal:16,vertical:8),child:SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PrepareRouteScreen(state:s))),icon:const Icon(Icons.route),label:const Padding(padding:EdgeInsets.all(12),child:Text('PREPARAR ROTA'))))),if(s.reviewCount>0)Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:SizedBox(width:double.infinity,child:OutlinedButton.icon(onPressed:()=>_reviewNext(context),icon:const Icon(Icons.warning_amber),label:Text('REVISAR ${s.reviewCount} ENDEREÇO${s.reviewCount==1?'':'S'}')))),if(visible.isEmpty)Expanded(child:Center(child:Text(active.isEmpty?'Nenhum endereço ativo.':'Nenhum endereço neste filtro.',textAlign:TextAlign.center)))else Expanded(child:ListView.builder(itemCount:visible.length,itemBuilder:(context,i){final p=visible[i];final original=s.packages.indexWhere((x)=>x.id==p.id);return ListTile(leading:CircleAvatar(child:Text('${original+1}')),title:Text(p.label),subtitle:Text(p.address.formatted.isEmpty?p.address.raw:p.address.formatted,maxLines:2,overflow:TextOverflow.ellipsis),trailing:Icon(_statusIcon(p)),onTap:()=>_package(context,original,p));}))]);}
 Widget _chip(String label,int count,_ActiveFilter value)=>Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:ChoiceChip(label:Text('$label ($count)'),selected:filter==value,onSelected:(_)=>setState(()=>filter=value)));
 IconData _statusIcon(DeliveryPackage p){if(p.status==DeliveryStatus.absent)return Icons.person_off_outlined;if(p.status==DeliveryStatus.addressProblem)return Icons.location_off_outlined;if(p.status==DeliveryStatus.skipped)return Icons.skip_next;return p.address.validation==ValidationStatus.confirmed?Icons.check_circle:Icons.warning_amber;}
 Widget _deliveredView(List<DeliveryPackage> delivered)=>delivered.isEmpty?const Center(child:Text('Nenhuma entrega concluída ainda.')):ListView.separated(padding:const EdgeInsets.symmetric(vertical:8),itemCount:delivered.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(context,i){final p=delivered[i];final when=p.completedAt;final address=p.address.formatted.isEmpty?p.address.raw:p.address.formatted;return ListTile(isThreeLine:true,leading:const CircleAvatar(child:Icon(Icons.check)),title:Row(children:[Expanded(child:Text(p.label,style:const TextStyle(fontWeight:FontWeight.w600))),if(when!=null)Text(_dateTime(when),style:Theme.of(context).textTheme.labelMedium)]),subtitle:Text('$address${p.shortTracking==null?'':'\nCódigo ${p.shortTracking}'}',maxLines:3,overflow:TextOverflow.ellipsis),trailing:p.physicalZone?.trim().isNotEmpty==true?Chip(label:Text(p.physicalZone!)):null);});
 String _dateTime(DateTime d){final local=d.toLocal();String two(int n)=>n.toString().padLeft(2,'0');final now=DateTime.now();final sameDay=now.year==local.year&&now.month==local.month&&now.day==local.day;return sameDay?'${two(local.hour)}:${two(local.minute)}':'${two(local.day)}/${two(local.month)} ${two(local.hour)}:${two(local.minute)}';}
 Widget _stat(String n,String t)=>Column(children:[Text(n,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text(t,style:const TextStyle(fontSize:12))]);
 Future<void> _retryPending(BuildContext context)async{setState(()=>retrying=true);try{final pos=await LocationService().current();final count=await widget.state.prepareRetryRoute(pos.latitude,pos.longitude,includeAddressProblems:true,includeSkipped:true);if(!context.mounted)return;if(count>0){setState(()=>filter=_ActiveFilter.pending);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$count parada${count==1?'':'s'} preparada${count==1?'':'s'} para nova tentativa. Confira a carga antes de sair.')));await Navigator.push(context,MaterialPageRoute(builder:(_)=>PrepareRouteScreen(state:widget.state)));}}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Não consegui preparar a 2ª tentativa: $e')));}finally{if(mounted)setState(()=>retrying=false);}}
 Future<void> _manual(BuildContext context)async{final r=await showAddressEditor(context,title:'Adicionar endereço');if(r!=null&&r.raw.isNotEmpty){await widget.state.addStructured(r.toAddress());}}
 Future<void> _edit(BuildContext context,int i,DeliveryPackage p)async{final r=await showAddressEditor(context,title:p.address.validation==ValidationStatus.confirmed?'Editar endereço':'Revisar ${p.label}',initial:p.address);if(r!=null&&r.raw.isNotEmpty){await widget.state.updateAddress(i,r.toAddress());}}
 Future<void> _reviewNext(BuildContext context)async{final i=widget.state.packages.indexWhere((p)=>p.address.validation!=ValidationStatus.confirmed&&p.status!=DeliveryStatus.delivered);if(i>=0)await _edit(context,i,widget.state.packages[i]);}
 Future<void> _pasteList(BuildContext context)async{final c=TextEditingController();final clip=await Clipboard.getData(Clipboard.kTextPlain);if(clip?.text?.trim().isNotEmpty==true)c.text=clip!.text!;if(!context.mounted){c.dispose();return;}final text=await showDialog<String>(context:context,builder:(d)=>AlertDialog(title:const Text('Colar lista de endereços'),content:SizedBox(width:500,child:TextField(controller:c,minLines:8,maxLines:14,decoration:const InputDecoration(hintText:'Cole todos de uma vez.\nUse um endereço por linha.',border:OutlineInputBorder()))),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancelar')),FilledButton.icon(onPressed:()=>Navigator.pop(d,c.text),icon:const Icon(Icons.playlist_add),label:const Text('Adicionar lista'))]));c.dispose();if(text?.trim().isNotEmpty==true){final n=await widget.state.addManyFromText(text!);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$n endereços adicionados. Revise os que estiverem com ⚠️.')));}}
 Future<void> _confirmClear(BuildContext context)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Limpar todos os pacotes?'),content:Text('Isso apagará os ${widget.state.packages.length} pacotes desta rota. Esta ação não pode ser desfeita.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Apagar tudo'))]));if(ok==true)await widget.state.clear();}
 Future<void> _package(BuildContext context,int i,DeliveryPackage p)async{await showModalBottomSheet(context:context,builder:(c)=>SafeArea(child:Wrap(children:[ListTile(title:Text(p.label),subtitle:Text(p.address.formatted.isEmpty?p.address.raw:p.address.formatted)),ListTile(leading:Icon(p.address.validation==ValidationStatus.confirmed?Icons.edit_location_alt:Icons.warning_amber),title:Text(p.address.validation==ValidationStatus.confirmed?'Editar endereço':'Revisar endereço'),onTap:(){Navigator.pop(c);WidgetsBinding.instance.addPostFrameCallback((_){if(context.mounted)_edit(context,i,p);});})])));}
}